data.nginx.conf:
events {}
http {
  server {
    listen 8000;
    location /oauth2/ {
      proxy_pass http://oauth2-proxy.keep-lab.svc.cluster.local:4180;
      proxy_set_header Host $http_host;
      proxy_set_header X-Real-IP $remote_addr;
      proxy_set_header X-Scheme $scheme;
      proxy_set_header X-Auth-Request-Redirect $request_uri;
    }
    location = /oauth2/sign_out {
      proxy_pass http://oauth2-proxy.keep-lab.svc.cluster.local:4180;
      proxy_set_header Host $http_host;
      proxy_set_header X-Real-IP $remote_addr;
      proxy_set_header X-Scheme $scheme;
      proxy_set_header X-Auth-Request-Redirect "/oauth2/sign_in?rd=/";
    }
    location = /oauth2/auth {
      proxy_pass http://oauth2-proxy.keep-lab.svc.cluster.local:4180;
      proxy_set_header Host $http_host;
      proxy_set_header X-Real-IP $remote_addr;
      proxy_set_header Content-Length "";
      proxy_pass_request_body off;
    }
    location /v2/ {
      auth_request /oauth2/auth;
      error_page 401 = /oauth2/start;
      auth_request_set $auth_email $upstream_http_x_auth_request_email;
      auth_request_set $auth_groups $upstream_http_x_auth_request_groups;
      proxy_set_header X-Auth-Request-Email $auth_email;
      proxy_set_header X-Auth-Request-Groups $auth_groups;
      # Browser requests are authenticated by oauth2-proxy above.
      proxy_set_header Authorization "";
      rewrite ^/v2/(.*)$ /$1 break;
      proxy_pass http://keep-backend.keep-lab.svc.cluster.local:8080;
    }
    location / {
      auth_request /oauth2/auth;
      error_page 401 = /oauth2/start;
      auth_request_set $auth_email $upstream_http_x_auth_request_email;
      auth_request_set $auth_groups $upstream_http_x_auth_request_groups;
      proxy_set_header X-Auth-Request-Email $auth_email;
      proxy_set_header X-Auth-Request-Groups $auth_groups;
      proxy_set_header Host $http_host;
      proxy_pass http://keep-frontend.keep-lab.svc.cluster.local:3000;
    }
  }
}
